def make_base(self):
    shape = cq.Workplane('XY').box(self.length, self.width, self.height)
    self.model = shape

def add_bosses(self):
    bosses = self.model.faces('>Z').workplane().rect(self.boss_spacing, self.boss_spacing, forConstruction=True).vertices().circle(self.boss_radius).extrude(self.boss_height, combine=False)
    self.model = self.model.union(bosses)
